INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2022, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2022): Língua Portuguesa Itens de 1 a 10 | 4 7 10 13 16 19 22 24 Arbitrária fortuna\! Desprezível Mais que essas almas vis, que a ti se humilham, Prosterne-se a teus pés o Brasil todo; Eu, nem curvo o joelho. \[…\] Não – reduzir-me a pó, roubar-me tudo, Porém nunca aviltar-me pode o fado; Quem a morte não teme, nada teme Eu nisto só confio. \[...\] Cingida a fronte de sangrentos loiros Horror jamais inspirará meu nome; Nunca a viúva há de pedir-me o esposo, Nem seu pai a criança. Nunca aspirei a flagelar humanos. Meu nome acabe, para sempre acabe, Se para libertar do eterno olvido Forem precisos crimes. \[…\] Exulta, velha Europa: o novo Império, Obra-prima do Céu\! Por fado ímpio Não será mais o teu rival ativo Em comércio e marinha. Aquele, que gigante inda no berço Se mostrava às nações, no berço mesmo É já cadáver de cruéis har', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Política Internacional', 'Organismos internacionais', 'Item 2 (TPS 2022): Política Internacional Itens de 11 a 22 Os processos e o projeto político da União Europeia (UE) estão atrelados historicamente à superação de crises internas e à construção de parcerias com outras regiões do mundo. A respeito do bloco da UE, julgue (C ou E) os itens a seguir. As perspectivas teóricas das Relações Internacionais são tão diversas quanto as possibilidades de definição de seu objeto  | A partir da Organização das Nações Unidas, a temática ambiental ganhou mais visibilidade, distinguindo-se um período até a reunião de Estocolmo, realizada em 1972, e outro que se seguiu a ele. 3 Em Estocolmo, foram discutidos aspectos vinculados à poluição atmosférica e foi decidida a criação do Programa das Nações Unidas para o Meio Ambiente. (Pnuma), que passou a comandar as discussões ambientais em escala mundial. 4 Outro momento de destaque foi a Conferência das Nações Unidas para o Meio Ambiente e Desenvolvimento (Cnumad), realizada no Rio de Janeiro em 1992. QUESTÃO', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2022, 'Política Internacional', NULL, 'Item 3 (TPS 2022) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2022, 'Português', 'Macroeconomia', 'Item 4 (TPS 2022): EDITAL No 1, DE 15 DE FEVEREIRO DE 2022 CONCURSO DE ADMISSÃO À CARREIRA DE DIPLOMATA CARGO: TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA Tipo Data da prova: “A” Domingo, 17/4/2022. • Você receberá do fiscal: o 1 (um) caderno da prova objetiva contendo 34 (trinta e quatro) questões, e cada questão será composta por | (quatro) itens; e o 1 (uma) folha de respostas personalizada. • Verifique se a numeração das questões, a paginação do caderno da prova objetiva e a codificação da folha de respostas estão corretas. • Quando autorizado pelo fiscal do IADES, no momento da identificação, escreva, no espaço apropriado da folha de respostas, com a sua caligrafia usual, a seguinte frase: Estuda, a frio, o coração alheio. • Você dispõe de 3 (três) horas para fazer a prova objetiva, devendo controlar o tempo, pois não haverá prorrogação desse prazo. Esse tempo inclui a marcação da folha de respostas. • Somente 1 (uma) hora após o início da prova, você poderá entregar sua folha de', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
